from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Baseline LU factorization kernel.
# We keep the standard right-looking algorithm but:
#  - use scalar accumulators (tmp/tmp2) inside the k-loops so that A[i, j]
#    is loaded/stored only once per (i, j), which reduces memory traffic and
#    improves vectorization.
#  - later, we parallelize the upper-triangular update across columns j,
#    which are independent for a fixed row i.
@proc
def kernel_lu_base(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    for i in seq(0, n):
        # Compute the L factors in row i: j = 0 .. i-1
        for j in seq(0, i):
            # Accumulate the dot product in a scalar to avoid repeated
            # loads/stores of A[i, j] inside the k-loop.
            tmp: DATA_TYPE
            tmp = A[i, j]
            for k in seq(0, j):
                tmp += -A[i, k] * A[k, j]
            tmp = tmp / A[j, j]
            A[i, j] = tmp

        # Compute the U factors in row i: j = i .. n-1
        for j in seq(i, n):
            tmp2: DATA_TYPE
            tmp2 = A[i, j]
            for k in seq(0, i):
                tmp2 += -A[i, k] * A[k, j]
            A[i, j] = tmp2


