kernel_lu_sched = kernel_lu_base

# Parallelize the second j-loop (upper-triangular / U update).
# For fixed i, each iteration of this loop:
#   - reads the same L row A[i, 0..i-1] and the same set of previous rows
#   - writes to a distinct element A[i, j]
# so iterations are independent and can safely run in parallel.
j2 = kernel_lu_sched.find_loop("j #1")
kernel_lu_sched = parallelize_loop(kernel_lu_sched, j2)

