from exo.libs.memories import DRAM


# In-place LU factorization without pivoting.
# A is overwritten with L (unit diagonal implied) and U.
@proc
def kernel_lu(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # Outer loop over rows.
    for i in seq(0, n):

        # Compute the strictly lower-triangular part of row i:
        #   L[i, j] for j in [0, i).
        # Each L[i, j] depends on previously computed entries L[i, k] (k < j)
        # and U[k, j], so this loop must remain sequential in j.
        for j in seq(0, i):
            # A[i, j] -= sum_{k=0}^{j-1} L[i, k] * U[k, j]
            for k in seq(0, j):
                A[i, j] += -A[i, k] * A[k, j]
            # Normalize by the diagonal U[j, j] to get L[i, j].
            A[i, j] = A[i, j] / A[j, j]

        # Compute the upper-triangular part of row i:
        #   U[i, j] for j in [i, n).
        #
        # We use an outer-product style update:
        #   for k in [0, i):
        #     for j in [i, n):
        #       A[i, j] -= L[i, k] * U[k, j]
        #
        # To make the column loop start at 0 and thus easier to tile, we
        # reindex j as j = i + jj with jj in [0, n - i).
        # This preserves the original computation while improving cache
        # locality when we later tile jj.
        for k in seq(0, i):
            for jj in seq(0, n - i):
                # Column index j = i + jj
                A[i, i + jj] += -A[i, k] * A[k, i + jj]


# --------------------
# Scheduling / optimization
# --------------------
# We tile the jj loop in the U update to improve cache locality and
# enable better use of hardware prefetching. The inner loop ji walks
# contiguous elements along the row (j dimension), which are laid out
# contiguously in memory in C row-major order.
J_TILE = 32  # tunable tile size for the column dimension

kernel_lu = divide_loop(
    kernel_lu,
    "jj",              # loop variable to tile (only appears in U update)
    J_TILE,            # tile size
    ("jo", "ji"),      # new outer and inner loop variables
    tail="guard",      # handle non-multiple tails safely with guards
)

# Additional optimizations (e.g., parallelize_loop on "jo" or more
# aggressive loop transformations) can be applied here if desired,
# provided they preserve the dependencies in the LU factorization.

EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D view to 1D pointer. */
  kernel_lu (/*ctxt=*/NULL, n,
             (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
